using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 renamed the discriminator property from "Discriminator" to "$type".
        // Preserve the EF8 name so existing 500K documents remain readable and
        // direct SQL queries that reference c.Discriminator keep working.
        configurationBuilder.Conventions.Remove(
            typeof(Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.CosmosDiscriminatorConvention));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 no longer prepends the type name to the id value.
            // Existing documents use "Product|<key>" format written by EF8.
            // Re-enable the legacy format so reads/writes stay compatible.
            entity.HasDiscriminator<string>("Discriminator").HasValue<Product>("Product");
            entity.Property(p => p.Id)
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

            // HasIndex is not supported by the Cosmos provider in EF9 — removed.
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

