using Microsoft.EntityFrameworkCore;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 changed two Cosmos defaults that break existing documents:
        //
        // 1. Discriminator property: renamed from "Discriminator" to "$type".
        //    Our 500K docs and direct SQL queries use c.Discriminator.
        //
        // 2. JSON id format: changed from "EntityType|Key" to just "Key".
        //    Our 500K docs have id values like "Product|123".
        //
        // HasDiscriminatorInJsonIds(true) re-enables the EF8 id format
        // ("Product|123") so existing documents remain addressable.
        modelBuilder.HasDiscriminatorInJsonIds(true);

        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Explicitly set the discriminator property name and value
            // to match what EF8 wrote into existing documents.
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product");

            // HasIndex is not supported by the Cosmos provider — removed.
        });
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

